def populate_sprint_case_numbers_and_snapshots(apps, schema_editor):
    Sprint = apps.get_model('qamanagement', 'Sprint')
    Assignment = apps.get_model('qamanagement', 'UseCaseAssignment')
    Ticket = apps.get_model('qamanagement', 'SprintTicket')

    for sprint in Sprint.objects.all().iterator():
        number = 1
        assignments = Assignment.objects.filter(sprint_id=sprint.pk).select_related('use_case').order_by('assigned_at', 'id')
        case_numbers = {}
        for assignment in assignments.iterator():
            use_case = assignment.use_case
            if use_case.pk not in case_numbers:
                case_numbers[use_case.pk] = number
                number += 1
            assignment.case_number = case_numbers[use_case.pk]
            assignment.has_sprint_snapshot = True
            assignment.snapshot_use_case_text = use_case.use_case_text
            assignment.snapshot_jira_ticket = use_case.jira_ticket
            assignment.snapshot_description = use_case.description
            assignment.snapshot_preconditions = use_case.preconditions
            assignment.snapshot_steps = use_case.steps
            assignment.snapshot_expected_results = use_case.expected_results
            assignment.snapshot_observed_results = use_case.observed_results
            assignment.save(update_fields=[
                'case_number', 'has_sprint_snapshot', 'snapshot_use_case_text',
                'snapshot_jira_ticket', 'snapshot_description', 'snapshot_preconditions',
                'snapshot_steps', 'snapshot_expected_results', 'snapshot_observed_results',
            ])
        for ticket in Ticket.objects.filter(sprint_id=sprint.pk).order_by('created_at', 'id').iterator():
            ticket.case_number = number
            ticket.save(update_fields=['case_number'])
            number += 1

        Sprint.objects.filter(pk=sprint.pk).update(next_case_number=number)


